"""Base provider protocols for VirtuJudge AI-ML.

Defines structural interfaces (typing.Protocol) for swappable AI/ML adapters.
"""

from pathlib import Path
from typing import Any, Literal, Protocol

from pydantic import BaseModel, Field, model_validator

from app.contracts import Finding, FollowUpQuestion, Limitation, PrimaryQuestion
from app.providers.types import (
    AudioObservation,
    DiarizationResult,
    DocumentChunk,
    TranscriptionResult,
    VisualObservation,
)


class ReportFeedbackResult(BaseModel):
    """Structured report feedback generated by a judge LLM provider."""

    executive_summary: str
    dimension_scores: dict[str, float] = Field(default_factory=dict)
    dimension_rationales: dict[str, str] = Field(default_factory=dict)
    team_strengths: list[Finding] = Field(default_factory=list)
    team_improvements: list[Finding] = Field(default_factory=list)
    member_strengths: dict[str, list[Finding]] = Field(default_factory=dict)
    member_improvements: dict[str, list[Finding]] = Field(default_factory=dict)
    recommendations: list[str] = Field(default_factory=list)


class AnswerAssessment(BaseModel):
    """Structured assessment of a team member's answer against a question and rubric."""

    assessment_text: str
    # "scored" is a real judgement (a genuinely poor answer can score 0.0);
    # "not_evaluated" means no usable judgement exists and score is None.
    status: Literal["scored", "not_evaluated"] = "scored"
    score: float | None = Field(default=0.0, ge=0.0, le=1.0)
    evidence_ids: list[str] = Field(default_factory=list)
    follow_up: FollowUpQuestion | None = None
    limitations: list[Limitation] = Field(default_factory=list)
    # Operational provenance, e.g. which model attempt produced the result.
    metadata: dict[str, Any] = Field(default_factory=dict)

    @model_validator(mode="after")
    def _status_matches_score(self) -> "AnswerAssessment":
        if self.status == "not_evaluated" and self.score is not None:
            raise ValueError("A not_evaluated assessment must not carry a score.")
        if self.status == "scored" and self.score is None:
            raise ValueError("A scored assessment requires a score.")
        return self


class SpeechProvider(Protocol):
    """Protocol for speech transcription providers."""

    async def transcribe(self, audio_path: Path) -> TranscriptionResult: ...


class DiarizationProvider(Protocol):
    """Protocol for speaker diarization providers."""

    async def diarize(self, audio_path: Path) -> DiarizationResult: ...


class VisionProvider(Protocol):
    """Protocol for computer vision and body language providers."""

    async def analyze_video(self, video_path: Path) -> list[VisualObservation]: ...


class AudioMetricsProvider(Protocol):
    """Protocol for acoustic analysis and prosody providers."""

    async def extract_metrics(self, audio_path: Path) -> list[AudioObservation]: ...


class DocumentProvider(Protocol):
    """Protocol for document ingestion, parsing, and vectorization."""

    async def extract_and_embed(
        self, doc_path: Path, *, asset_version_id: str = ""
    ) -> list[DocumentChunk]: ...


class JudgeModelProvider(Protocol):
    """Protocol for LLM reasoning and question generation providers."""

    async def generate_questions(
        self,
        transcript: str,
        rubric_id: str,
        document_chunks: list[DocumentChunk] | None = None,
        evidence_bundle: Any = None,
    ) -> list[PrimaryQuestion]: ...

    async def assess_answer(
        self,
        answer_transcript: str,
        question_text: str,
        rubric_dimension: str,
        *,
        remaining_follow_ups: int = 0,
    ) -> AnswerAssessment: ...

    async def generate_report_feedback(
        self,
        *,
        transcript_summary: str,
        qa_summary: str,
        speaker_profiles: dict[str, Any],
        rubric_id: str = "startup_pitch",
    ) -> ReportFeedbackResult: ...


class EmbeddingProvider(Protocol):
    """Protocol for text embedding generation providers."""

    async def embed(self, texts: list[str]) -> list[list[float]]: ...


__all__ = [
    "AnswerAssessment",
    "AudioMetricsProvider",
    "DiarizationProvider",
    "DocumentProvider",
    "EmbeddingProvider",
    "JudgeModelProvider",
    "ReportFeedbackResult",
    "SpeechProvider",
    "VisionProvider",
]
